using System.ComponentModel;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

// --- Build the chat client pipeline with function-invocation support ---
IChatClient chatClient = new ChatClientBuilder(
        new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

// --- Define tools ---
var tools = new ResearchTools();
var aiTools = new AITool[]
{
    AIFunctionFactory.Create(tools.SearchWeb),
    AIFunctionFactory.Create(tools.SaveNote),
    AIFunctionFactory.Create(tools.GetNotes),
};

// --- Create the agent ---
ChatClientAgent agent = chatClient.AsAIAgent(new ChatClientAgentOptions
{
    Name = "ResearchAgent",
    Description = "An AI agent that researches topics by searching the web and taking notes.",
    ChatOptions = new()
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
        Tools = [.. aiTools],
    },
});

agent.Instructions = $"""
    You are a research assistant. Your goal is to thoroughly research the given topic.

    Follow this workflow:
    1. Search the web for information about the topic using different search queries.
    2. Save important findings as notes using the SaveNote tool.
    3. After gathering enough information (at least 3 searches), retrieve all your notes.
    4. Write a comprehensive summary that synthesizes your findings.

    Always cite the sources you found. Be thorough but concise.
    """;

// --- Run the agent ---
var session = await agent.CreateSessionAsync();
var runOptions = new ChatClientAgentRunOptions(new ChatOptions { Temperature = 0f });

await foreach (var update in agent.RunStreamingAsync(topic, session, runOptions))
{
    Console.Write(update.Text);
}

Console.WriteLine("\n\n📝 Notes collected during research:");
Console.WriteLine(new string('─', 50));
foreach (var note in tools.AllNotes)
{
    Console.WriteLine($"  • [{note.Category}] {note.Content}");
}

return;

static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrWhiteSpace(input)
        ? throw new InvalidOperationException("A research topic is required.")
        : input;
}

// --- Tool implementations ---

public sealed class ResearchNote
{
    public required string Category { get; init; }
    public required string Content { get; init; }
}

public sealed class SearchResult
{
    public required string Title { get; init; }
    public required string Snippet { get; init; }
    public required string Url { get; init; }
}

public sealed class ResearchTools
{
    private readonly List<ResearchNote> _notes = [];
    private int _searchCount;

    public IReadOnlyList<ResearchNote> AllNotes => _notes;

    [Description("Search the web for information on a query. Returns a list of results with titles, snippets, and URLs.")]
    public IReadOnlyList<SearchResult> SearchWeb(
        [Description("The search query to look up on the web.")] string query)
    {
        _searchCount++;
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        // Simulated search results keyed by query keywords.
        // In production, replace with a real search API (e.g., Bing Search).
        var results = GenerateSimulatedResults(query, _searchCount);

        Console.WriteLine($"     Found {results.Count} results.");
        return results;
    }

    [Description("Save an important finding as a research note with a category label.")]
    public string SaveNote(
        [Description("Category for the note, e.g. 'definition', 'history', 'statistic', 'opinion'.")] string category,
        [Description("The content of the research note.")] string content)
    {
        _notes.Add(new ResearchNote { Category = category, Content = content });
        Console.WriteLine($"  📌 Note saved: [{category}] {Truncate(content, 60)}");
        return $"Note saved successfully. Total notes: {_notes.Count}";
    }

    [Description("Retrieve all research notes collected so far.")]
    public IReadOnlyList<ResearchNote> GetNotes()
    {
        Console.WriteLine($"  📋 Retrieved {_notes.Count} notes.");
        return _notes;
    }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : string.Concat(text.AsSpan(0, maxLength), "...");

    private static List<SearchResult> GenerateSimulatedResults(string query, int seed)
    {
        // Deterministic simulated results so the app is runnable without a search API.
        var lowerQuery = query.ToLowerInvariant();
        var results = new List<SearchResult>();

        if (lowerQuery.Contains("quantum") || lowerQuery.Contains("computing"))
        {
            results.AddRange([
                new() { Title = "What Is Quantum Computing? - IBM", Snippet = "Quantum computing uses qubits that can exist in superposition, enabling parallel computation. Unlike classical bits (0 or 1), qubits leverage quantum phenomena.", Url = "https://www.ibm.com/quantum/what-is-quantum-computing" },
                new() { Title = "Quantum Computing Progress 2025 - Nature", Snippet = "Recent breakthroughs include error-corrected logical qubits and 1000+ qubit processors. Google and IBM lead commercial efforts.", Url = "https://www.nature.com/articles/quantum-2025" },
                new() { Title = "Applications of Quantum Computing - MIT Tech Review", Snippet = "Key applications include cryptography, drug discovery, optimization problems, and climate modeling. Market projected at $65B by 2030.", Url = "https://www.technologyreview.com/quantum-applications" },
            ]);
        }
        else if (lowerQuery.Contains("history") || lowerQuery.Contains("origin"))
        {
            results.AddRange([
                new() { Title = "History of Computing Concepts - Wikipedia", Snippet = "Richard Feynman proposed quantum computing in 1981. Peter Shor developed the first quantum algorithm in 1994. D-Wave released the first commercial system in 2011.", Url = "https://en.wikipedia.org/wiki/Quantum_computing_history" },
                new() { Title = "Timeline of Quantum Computing Milestones", Snippet = "2019: Google claims quantum supremacy. 2023: IBM unveils 1,121-qubit Condor processor. 2024: First error-corrected computations demonstrated.", Url = "https://quantumtimeline.com/milestones" },
            ]);
        }
        else if (lowerQuery.Contains("challenge") || lowerQuery.Contains("limitation") || lowerQuery.Contains("problem"))
        {
            results.AddRange([
                new() { Title = "Challenges in Quantum Computing - IEEE Spectrum", Snippet = "Major challenges include qubit decoherence, error rates, extreme cooling requirements (near absolute zero), and the need for new programming paradigms.", Url = "https://spectrum.ieee.org/quantum-challenges" },
                new() { Title = "The Quantum Error Correction Problem - Science", Snippet = "Current quantum computers require thousands of physical qubits per logical qubit for error correction, limiting practical applications.", Url = "https://www.science.org/quantum-error-correction" },
            ]);
        }
        else
        {
            results.AddRange([
                new() { Title = $"Research on: {query} - Encyclopedia", Snippet = $"Comprehensive overview of {query} covering fundamental concepts, recent developments, and future outlook in the field.", Url = $"https://encyclopedia.example.com/{Uri.EscapeDataString(query)}" },
                new() { Title = $"{query} - Latest Developments", Snippet = $"Recent advances in {query} show promising results across multiple domains. Researchers continue to push boundaries.", Url = $"https://research.example.com/{Uri.EscapeDataString(query)}" },
                new() { Title = $"Understanding {query} - Academic Review", Snippet = $"A peer-reviewed analysis of {query} examining methodology, key findings, and implications for the broader field.", Url = $"https://academic.example.com/review/{Uri.EscapeDataString(query)}" },
            ]);
        }

        return results;
    }
}

