 using System.ComponentModel;
 using System.Text.Json;
 using Microsoft.Agents.AI;
 using Microsoft.Extensions.AI;
 using OpenAI;

 // --- Configuration ---
 var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable before running.");

 var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

 var topic = args.Length > 0
     ? string.Join(' ', args)
     : PromptForTopic();

 Console.WriteLine($"\n🔍 Researching: {topic}\n");

 // --- Build the chat client pipeline with function-invocation support ---
 IChatClient chatClient = new ChatClientBuilder(
         new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient())
     .UseFunctionInvocation()
     .Build();

 // --- Define tools ---
 var tools = new ResearchTools();
 var aiTools = new AITool[]
 {
     AIFunctionFactory.Create(tools.SearchWeb),
     AIFunctionFactory.Create(tools.SaveNote),
     AIFunctionFactory.Create(tools.GetNotes),
 };

 // --- Create the agent ---
 var instructions = """
     You are a research assistant. Your goal is to thoroughly research the given topic.

     Follow this workflow:
     1. Search the web for information about the topic using different search queries.
     2. Save important findings as notes using the SaveNote tool.
     3. After gathering enough information (at least 3 searches), retrieve all your notes.
     4. Write a comprehensive summary that synthesizes your findings.

     Always cite the sources you found. Be thorough but concise.
     """;

 ChatClientAgent agent = chatClient.AsAIAgent(
     name: "ResearchAgent",
     description: "An AI agent that researches topics by searching the web and taking notes.",
     instructions: instructions,
     tools: [.. aiTools]);

 // --- Run the agent ---
 var session = await agent.CreateSessionAsync();
 var runOptions = new ChatClientAgentRunOptions(new ChatOptions { Temperature = 0f });

 await foreach (var update in agent.RunStreamingAsync(topic, session, runOptions))
 {
     Console.Write(update.Text);
 }

 Console.WriteLine("\n\n📝 Notes collected during research:");
 Console.WriteLine(new string('─', 50));
 foreach (var note in tools.AllNotes)
 {
     Console.WriteLine($"  • [{note.Category}] {note.Content}");
 }

 return;

 static string PromptForTopic()
 {
     Console.Write("Enter a research topic: ");
     var input = Console.ReadLine()?.Trim();
     return string.IsNullOrWhiteSpace(input)
         ? throw new InvalidOperationException("A research topic is required.")
         : input;
 }

