 {
     public required string Category { get; init; }
     public required string Content { get; init; }
 }

 public sealed class SearchResult
 {
     public required string Title { get; init; }
     public required string Snippet { get; init; }
     public required string Url { get; init; }
 }

 public sealed class ResearchTools
 {
     private readonly List<ResearchNote> _notes = [];
     private int _searchCount;

     public IReadOnlyList<ResearchNote> AllNotes => _notes;

     [Description("Search the web for information on a query. Returns a list of results with titles, snippets, and URLs.")]
     public IReadOnlyList<SearchResult> SearchWeb(
         [Description("The search query to look up on the web.")] string query)
     {
         _searchCount++;
